body.script:
import { initializeApp } from "https://www.gstatic.com/firebasejs/12.19.0/firebase-app.js";
import { getFirestore, collection, query, where, getDocs } from "https://www.gstatic.com/firebasejs/12.19.0/firebase-firestore.js";
const firebaseConfig = {
  apiKey: "AIzaSyBADCK9FGULv7NPzMitfNq-_Wh8LFjf4nk",
  authDomain: "zedlinker-55555.firebaseapp.com",
  projectId: "zedlinker-55555",
  storageBucket: "zedlinker-55555.firebasestorage.app",
  messagingSenderId: "710796734605",
  appId: "1:710796734605:web:fc6be519c1876fa77a32c4"
};
const app = initializeApp(firebaseConfig);
const db = getFirestore(app);
function createSlug(text){
  if(!text) return '';
  return text.toString().toLowerCase().trim().replace(/[^a-z0-9\s-]/g, '').replace(/\s+/g, '-').replace(/-+/g, '-').substring(0,80).replace(/^-|-$/g,'');
}
function escapeXml(s){ return s.replace(/[<>&'"]/g, c=>({ '<':'<','>':'>','&':'&',"'":''','"':'"'}[c])); }
async function buildSitemap(){
  const today = new Date().toISOString().split('T')[0];
  let urls = [];
  urls.push({loc:'https://zedlinker.store/', lastmod:today, changefreq:'daily', priority:'1.0'});
  urls.push({loc:'https://zedlinker.store/ads.html', lastmod:today, changefreq:'daily', priority:'0.9'});
  const categories = ['Education','Entertainment','Business','Jobs','Technology','News','Gaming'];
  categories.forEach(cat=>{ urls.push({loc:`https://zedlinker.store/?category=${encodeURIComponent(cat)}`, lastmod:today, changefreq:'daily', priority:'0.8'}); });
  const types = ['whatsapp_group','whatsapp_channel','telegram_group','telegram_channel'];
  types.forEach(t=>{ urls.push({loc:`https://zedlinker.store/?type=${t}`, lastmod:today, changefreq:'daily', priority:'0.8'}); });
  try{
    const [linksSnap, productsSnap, blogsSnap, adsSnap] = await Promise.all([
      getDocs(query(collection(db, 'links'), where('status','==','approved'))),
      getDocs(collection(db, 'products')),
      getDocs(collection(db, 'blogs')),
      getDocs(query(collection(db, 'ads'), where('status','==','approved')))
    ]);
    linksSnap.forEach(doc=>{
      const d = doc.data(); const id = doc.id; const name = d.name || d.title || id;
      const slug = createSlug(name) || id; const type = d.type || 'whatsapp_group';
      const lastmod = d.createdAt?.toDate ? d.createdAt.toDate().toISOString().split('T')[0] : today;
      urls.push({loc:`https://zedlinker.store/link/${slug}-${id}`, lastmod, changefreq:'weekly', priority:'0.8'});
      urls.push({loc:`https://zedlinker.store/?type=${type}&id=${id}`, lastmod, changefreq:'weekly', priority:'0.8'});
    });
    productsSnap.forEach(doc=>{
      const d = doc.data(); const id = doc.id; const title = d.title || id;
      const slug = createSlug(title) || id;
      const lastmod = d.createdAt?.toDate ? d.createdAt.toDate().toISOString().split('T')[0] : today;
      urls.push({loc:`https://zedlinker.store/product.html?id=${id}`, lastmod, changefreq:'weekly', priority:'0.8'});
      urls.push({loc:`https://zedlinker.store/product/${slug}-${id}`, lastmod, changefreq:'weekly', priority:'0.8'});
    });
    blogsSnap.forEach(doc=>{
      const d = doc.data(); const id = doc.id; const title = d.title || id;
      const slug = createSlug(title) || id;
      const lastmod = d.createdAt?.toDate ? d.createdAt.toDate().toISOString().split('T')[0] : today;
      urls.push({loc:`https://zedlinker.store/blog-details.html?id=${id}`, lastmod, changefreq:'weekly', priority:'0.9'});
      urls.push({loc:`https://zedlinker.store/blog/${slug}-${id}`, lastmod, changefreq:'weekly', priority:'0.9'});
    });
    adsSnap.forEach(doc=>{
      const d = doc.data(); const id = doc.id; const title = d.title || id;
      const slug = createSlug(title) || id;
      const lastmod = d.createdAt?.toDate ? d.createdAt.toDate().toISOString().split('T')[0] : today;
      urls.push({loc:`https://zedlinker.store/ad-details.html?id=${id}`, lastmod, changefreq:'weekly', priority:'0.7'});
    });
  }catch(e){ console.error(e); }
  let xml = `\n\n`;
  urls.forEach(u=>{ xml += `  \n    ${escapeXml(u.loc)}\n    ${u.lastmod}\n    ${u.changefreq}\n    ${u.priority}\n  \n`; });
  xml += ``;
  document.open(); document.write(xml); document.close();
}
buildSitemap();
